package net.officefloor.hq.app;

import java.math.BigDecimal;
import net.officefloor.web.ObjectResponse;

/**
 * GET /api/dashboard — the home summary: the number of clients and projects, and the outstanding
 * total (the sum of every UNPAID invoice's amount across all projects — the money still owed).
 */
public class DashboardLogic {

    public void service(ClientRepository clients, ProjectRepository projects,
            InvoiceRepository invoices, ObjectResponse<DashboardView> response) {
        long clientsCount = clients.count();
        long projectsCount = projects.count();
        BigDecimal outstandingTotal = invoices.findByStatusOrderByIdAsc("UNPAID").stream()
                .map(Invoice::getAmount)
                .reduce(BigDecimal.ZERO, BigDecimal::add);
        response.send(new DashboardView(clientsCount, projectsCount, outstandingTotal));
    }
}

package net.officefloor.hq.app;

import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;

/** Data access for {@link Invoice}. A Spring bean, injected into the OfficeFloor logic classes. */
public interface InvoiceRepository extends JpaRepository<Invoice, Long> {

    /** Every invoice across all projects, oldest first, so the list is stable across loads. */
    List<Invoice> findAllByOrderByIdAsc();

    /** A project's invoices, oldest first, so the list is stable across loads. */
    List<Invoice> findByProjectIdOrderByIdAsc(Long projectId);

    /** A project's invoices, earliest due date first (id as a stable tie-breaker). */
    List<Invoice> findByProjectIdOrderByDueDateAscIdAsc(Long projectId);

    /** Every invoice with the given status (e.g. UNPAID), oldest first — used to total what is owed. */
    List<Invoice> findByStatusOrderByIdAsc(String status);
}

